// Charts copied, cut, pasted and duplicated in the spreadsheet editor: with the clipboard
// events Ctrl/Cmd+C, X and V arrive as, with Ctrl/Cmd+D, from the menu of a chart and by the
// calls of the view; on the same sheet and on another one; beside the clipboard of the cells.
//
// No screenshots. Every workbook is generated by code.
import type { Page } from '@playwright/test';
import { UNKNOWN, richBook } from '../test/chart-copy-fixtures';
import { chartWorkbook, sheetData } from '../test/chart-fixtures';
import { expect, test } from './helpers';

const MOUSE_ONLY = 'a mouse is needed';
const HOME = { top: 5, left: 0, bottom: 17, right: 3 };
/** The frame HOME is drawn in, CSS pixels of the canvas (header 72 x 22, columns 64 wide, rows 20 high). */
const FRAME = { x: 72, y: 22 + 5 * 20, width: 4 * 64, height: 13 * 20 };

const book = () =>
  chartWorkbook({
    sheet: sheetData([
      ['Ad', 'Adet'],
      ['a', 10],
      ['b', 20],
      ['c', 40],
    ]),
    sheets: [{ name: 'Other', xml: sheetData([['x', 1]]) }],
  });

async function mount(page: Page, bytes: Uint8Array | number[], options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes as Uint8Array).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', 'api', `return ${code}`)((window as any).__editor.view, (window as any).BymOffice), code);
const charts = (page: Page): Promise<any[]> => view(page, 'view.charts()') as Promise<any[]>;
const notice = (page: Page) => page.evaluate(() => (window as any).__events.filter((event: any) => event.type === 'notice').slice(-1)[0]?.message);
const saved = (page: Page) => page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array));

interface Clip {
  text: string;
  html: string;
}

/** A clipboard event in the grid: what the view put on the clipboard (copy, cut), or what it is given to paste. */
function clipboard(page: Page, type: 'copy' | 'cut' | 'paste', give?: Partial<Clip>): Promise<Clip> {
  return page.evaluate(
    ([type, text, html]) => {
      const data = new DataTransfer();
      if (text !== null) data.setData('text/plain', text);
      if (html !== null) data.setData('text/html', html);
      let event: Event | undefined;
      try {
        event = new ClipboardEvent(type, { clipboardData: data, bubbles: true, cancelable: true });
      } catch {
        event = undefined;
      }
      // Some browsers give a scripted clipboard event a clipboard of their own instead of the one passed in.
      if (!event || (event as ClipboardEvent).clipboardData !== data) {
        event = new Event(type, { bubbles: true, cancelable: true });
        Object.defineProperty(event, 'clipboardData', { value: data });
      }
      document.querySelector('#host .bym-input')!.dispatchEvent(event);
      return { text: data.getData('text/plain'), html: data.getData('text/html') };
    },
    [type, give && give.text !== undefined ? give.text : null, give && give.html !== undefined ? give.html : null] as [string, string | null, string | null],
  );
}

/** A key pressed in the grid. */
function key(page: Page, init: KeyboardEventInit): Promise<boolean> {
  return page.evaluate((init) => {
    const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
    document.querySelector('#host .bym-input')!.dispatchEvent(event);
    return event.defaultPrevented;
  }, init);
}

async function addPlain(page: Page): Promise<void> {
  await view(page, `(view.addChart({ type: 'column', range: { top: 0, left: 0, bottom: 3, right: 1 }, anchor: ${JSON.stringify(HOME)}, legend: 'none', title: 'Adetler' }), view.selectChart(undefined))`);
}

/** Where the top left corner of a chart stands: the cell, and how far into it (EMU). */
const boxOf = (page: Page, id: number) =>
  view(page, `(() => { const a = view.charts()[${id}].anchor; return { col: a.from.col, row: a.from.row, colOff: a.from.colOff, rowOff: a.from.rowOff }; })()`) as Promise<{ col: number; row: number; colOff: number; rowOff: number }>;

test.describe('charts are copied', () => {
  test('copy and paste with a chart selected put a copy beside it, which is selected; undo takes it away in one step', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, 'view.selectChart(0)');
    const put = await clipboard(page, 'copy');
    expect(put.text, 'a word stands for the chart').toBe('Chart');
    expect(put.html).toMatch(/^<span data-bym-chart="[a-z0-9]+">Chart<\/span>$/);
    expect(put.html, 'nothing of the file is on the clipboard').not.toContain('Adetler');
    expect((await charts(page)).length).toBe(1);

    await clipboard(page, 'paste', put);
    const list = await charts(page);
    expect(list.length).toBe(2);
    expect(await view(page, 'view.selectedChart'), 'the copy is selected').toBe(1);
    expect(list[1].title).toBe('Adetler');
    expect(list[1].series).toEqual(list[0].series);
    // 24 pixels right and down: the frame starts at A6, the copy 24 pixels into A7.
    expect(await boxOf(page, 1)).toEqual({ col: 0, row: 6, colOff: 24 * 9525, rowOff: 4 * 9525 });
    expect(await notice(page)).toBeUndefined();

    // A second paste goes beside the copy, not onto it.
    await clipboard(page, 'paste', put);
    expect((await charts(page)).length).toBe(3);
    expect(await boxOf(page, 2)).toEqual({ col: 0, row: 7, colOff: 48 * 9525, rowOff: 8 * 9525 });

    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await charts(page)).length).toBe(1);
    await view(page, 'view.redo()');
    expect((await charts(page)).length).toBe(2);
  });

  test('Ctrl+D duplicates the selected chart, and cut and paste move it to the active cell', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, 'view.selectChart(0)');
    expect(await key(page, { key: 'd', code: 'KeyD', ctrlKey: true }), 'the key is taken: the browser does nothing with it').toBe(true);
    expect((await charts(page)).length).toBe(2);
    expect(await view(page, 'view.selectedChart')).toBe(1);
    expect(await key(page, { key: 'd', code: 'KeyD', metaKey: true })).toBe(true);
    expect((await charts(page)).length).toBe(3);
    await view(page, '(view.undo(), view.undo())');
    expect((await charts(page)).length).toBe(1);

    // Cut: the chart goes as one step, and the cells under it are not touched.
    await view(page, 'view.selectChart(0)');
    const put = await clipboard(page, 'cut');
    expect((await charts(page)).length).toBe(0);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 1, 1).value')).toBe(10);
    // With cells selected the chart is pasted at the active cell.
    await view(page, 'view.select(api.parseRange("C3"))');
    await clipboard(page, 'paste', put);
    expect((await charts(page)).length).toBe(1);
    expect(await boxOf(page, 0)).toEqual({ col: 2, row: 2, colOff: 0, rowOff: 0 });
    expect(await view(page, 'view.selectedChart')).toBe(0);
    await view(page, '(view.undo(), view.undo())');
    expect(await boxOf(page, 0), 'both steps undone: the chart is where it was').toEqual({ col: 0, row: 5, colOff: 0, rowOff: 0 });
  });

  test('the clipboard of the cells and that of a chart do not get in each other\'s way: what was copied last is pasted', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    // A chart, then cells: the cells are pasted.
    await view(page, 'view.selectChart(0)');
    const chart = await clipboard(page, 'copy');
    await view(page, '(view.selectChart(undefined), view.select(api.parseRange("A1:B2")))');
    const cells = await clipboard(page, 'copy');
    expect(cells.html).toContain('data-bym-copy=');
    expect(await view(page, 'view.hasChartCopy'), 'the chart is no longer held').toBe(false);
    await view(page, 'view.select(api.parseRange("D1"))');
    await clipboard(page, 'paste', cells);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 1, 4).value')).toBe(10);
    expect((await charts(page)).length).toBe(1);
    // The clipboard of a copy of a chart that is no longer held (an older one, one of another view): no chart is
    // pasted, and the word that stood for it is not written into a cell either. That is said.
    await view(page, 'view.select(api.parseRange("F1"))');
    await clipboard(page, 'paste', chart);
    expect((await charts(page)).length, 'a mark that is not the one held pastes no chart').toBe(1);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 0, 5)?.value'), 'nor text').toBeUndefined();
    expect(await notice(page)).toBe('The chart on the clipboard was copied elsewhere and cannot be pasted here: copy the chart again');
    // Something else arrives on the clipboard: the chart that was held is held no longer.
    await view(page, '(view.selectChart(0), view.copyChart(), view.selectChart(undefined), view.select(api.parseRange("F3")))');
    expect(await view(page, 'view.hasChartCopy')).toBe(true);
    await clipboard(page, 'paste', { text: 'from elsewhere', html: '<b>from elsewhere</b>' });
    expect(await view(page, 'view.hasChartCopy')).toBe(false);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 2, 5).value')).toBe('from elsewhere');

    // Cells, then a chart: the chart is pasted, at the active cell.
    await view(page, 'view.selectChart(0)');
    const again = await clipboard(page, 'copy');
    await view(page, '(view.selectChart(undefined), view.select(api.parseRange("B20")))');
    await clipboard(page, 'paste', again);
    expect((await charts(page)).length).toBe(2);
    expect(await boxOf(page, 1)).toEqual({ col: 1, row: 19, colOff: 0, rowOff: 0 });
    // The same word without the mark is text.
    await view(page, '(view.selectChart(undefined), view.select(api.parseRange("H1")))');
    await clipboard(page, 'paste', { text: 'Chart' });
    expect((await charts(page)).length).toBe(2);
    expect(await view(page, 'api.getCell(view.workbook.sheets[0], 0, 7).value')).toBe('Chart');
  });

  test('a chart pasted on another sheet shows the cells of the sheet it came from, in the file as well', async ({ page }) => {
    await mount(page, await book());
    await addPlain(page);
    await view(page, 'view.selectChart(0)');
    const put = await clipboard(page, 'copy');
    await view(page, 'view.setActiveSheet(1)');
    await clipboard(page, 'paste', put);
    const list = await charts(page);
    expect(list.length).toBe(1);
    expect(list[0].series).toEqual([{ nameRef: 'Sayfa1!$B$1', categories: 'Sayfa1!$A$2:$A$4', values: 'Sayfa1!$B$2:$B$4' }]);
    // A row inserted on the first sheet: both charts follow.
    await view(page, '(view.setActiveSheet(0), view.insertRows(0, 1), view.setActiveSheet(1))');
    expect((await charts(page))[0].series[0].values).toBe('Sayfa1!$B$3:$B$5');
    const bytes = await saved(page);
    await mount(page, bytes);
    expect(((await view(page, 'view.workbook.sheets.map((sheet) => (sheet.drawings || []).length)')) as number[])).toEqual([1, 1]);
    await view(page, 'view.setActiveSheet(1)');
    expect((await charts(page))[0].series[0].values).toBe('Sayfa1!$B$3:$B$5');
  });

  test('the menu of a chart cuts, copies, pastes and duplicates it', async ({ page, hasTouch }) => {
    test.skip(hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    await addPlain(page);
    const box = await page.locator('#host .bym-canvas').boundingBox();
    if (!box) throw new Error('the canvas has no box');
    const centre = { x: box.x + FRAME.x + FRAME.width / 2, y: box.y + FRAME.y + FRAME.height / 2 };
    const open = async () => {
      await page.mouse.click(centre.x, centre.y, { button: 'right' });
      await expect(page.locator('#host .bym-menu')).toBeVisible();
    };
    const item = (name: string) => page.locator('#host .bym-menu').getByRole('menuitem', { name, exact: true });
    await open();
    await expect(page.locator('#host .bym-menu [role="menuitem"]')).toHaveText(['Edit chart…', 'Cut', 'Copy', 'Paste', 'Duplicate', 'Delete chart']);
    await item('Duplicate').click();
    expect((await charts(page)).length).toBe(2);
    expect(await view(page, 'view.selectedChart')).toBe(1);
    await view(page, 'view.undo()');
    // Copy from the menu holds the chart; pasted by a call, it is there twice.
    await open();
    await item('Copy').click();
    expect(await view(page, 'view.hasChartCopy')).toBe(true);
    expect(await view(page, 'view.pasteChart()')).toBe(1);
    await view(page, 'view.undo()');
    await open();
    await item('Cut').click();
    expect((await charts(page)).length).toBe(0);
    expect(await view(page, 'view.pasteChart({ row: 2, col: 1 })')).toBe(0);
    expect(await boxOf(page, 0)).toEqual({ col: 1, row: 2, colOff: 0, rowOff: 0 });
  });

  test('a read-only view copies a chart and pastes none', async ({ page, hasTouch }) => {
    const filled = await (async () => {
      await mount(page, await book());
      await addPlain(page);
      return saved(page);
    })();
    await mount(page, filled, { readOnly: true });
    expect(await view(page, 'view.hasChartCopy')).toBe(false);
    const put = (await view(page, 'view.copyChart(0)')) as Clip;
    expect(put.html).toContain('data-bym-chart=');
    expect(await view(page, 'view.hasChartCopy')).toBe(true);
    expect(await view(page, 'view.pasteChart()')).toBe(-1);
    expect(await view(page, 'view.duplicateChart(0)')).toBe(-1);
    // Cut only copies.
    await view(page, 'view.cutChart(0)');
    expect((await charts(page)).length).toBe(1);
    await clipboard(page, 'paste', put);
    expect((await charts(page)).length).toBe(1);
    if (!hasTouch) {
      const box = await page.locator('#host .bym-canvas').boundingBox();
      if (!box) throw new Error('the canvas has no box');
      await page.mouse.click(box.x + FRAME.x + FRAME.width / 2, box.y + FRAME.y + FRAME.height / 2, { button: 'right' });
      await expect(page.locator('#host .bym-menu [role="menuitem"]')).toHaveText(['Copy']);
      expect(await view(page, 'view.selectedChart'), 'no chart is selected in a view that changes nothing').toBeUndefined();
    }
    // Made editable, the view pastes what it holds.
    await page.keyboard.press('Escape');
    await view(page, 'view.setReadOnly(false)');
    expect(await view(page, 'view.pasteChart()')).toBe(1);
  });

  test('the copy of a chart of a file keeps the formatting of its part, with a style, colours and a picture of its own', async ({ page }) => {
    const file = await richBook();
    await mount(page, file);
    expect(((await charts(page)) as any[]).map((chart) => chart.editable)).toEqual(['parts', 'parts']);
    const put = (await view(page, 'view.copyChart(0)')) as Clip;
    await view(page, 'view.setActiveSheet(1)');
    await clipboard(page, 'paste', put);
    const list = await charts(page);
    expect(list.length).toBe(1);
    expect(list[0].editable, 'the copy is changed the way the chart is').toBe('parts');
    expect(list[0].ofFile).toBe(false);
    const bytes = await saved(page);
    const parts = await page.evaluate(async (bytes) => {
      const zip = (window as any).BymOffice.ZipArchive.read(new Uint8Array(bytes));
      const names: string[] = zip.names().filter((name: string) => /^xl\/(charts|media)\//.test(name)).sort();
      const text = async (name: string) => new TextDecoder().decode(await zip.read(name));
      return { names, same: (await text('xl/charts/chart3.xml')) === (await text('xl/charts/chart1.xml')), rels: await text('xl/charts/_rels/chart3.xml.rels') };
    }, bytes);
    expect(parts.names).toEqual(['xl/charts/_rels/chart1.xml.rels', 'xl/charts/_rels/chart3.xml.rels', 'xl/charts/chart1.xml', 'xl/charts/chart2.xml', 'xl/charts/chart3.xml', 'xl/charts/colors1.xml', 'xl/charts/colors2.xml', 'xl/charts/style1.xml', 'xl/charts/style2.xml', 'xl/media/image1.png', 'xl/media/image2.png']);
    expect(parts.same, 'the part of the copy is the part of the chart').toBe(true);
    expect(parts.rels).toContain('Target="style2.xml"');
    // The paste undone: the file that was opened, byte for byte.
    await view(page, '(view.undo(), view.setActiveSheet(0))');
    expect(await saved(page)).toEqual(Array.from(file));
  });

  test('a chart that cannot be copied says so in the language of the view, and what a copy leaves out is said', async ({ page }) => {
    await mount(page, await richBook({ first: UNKNOWN }), { locale: 'tr' });
    await view(page, 'view.selectChart(0)');
    const put = await clipboard(page, 'copy');
    expect(put.html, 'nothing is put on the clipboard').toBe('');
    expect(await notice(page)).toBe('Bu grafik kopyalanamaz: dosyasındaki içerik kopyada korunamıyor');
    expect(await key(page, { key: 'd', ctrlKey: true })).toBe(true);
    expect((await charts(page)).length).toBe(2);

    await mount(page, await richBook({ shapes: true }));
    await view(page, 'view.selectChart(0)');
    await key(page, { key: 'd', ctrlKey: true });
    expect((await charts(page)).length).toBe(3);
    await expect.poll(() => notice(page)).toBe('The copy was made without the shapes drawn over the chart');
    // Rows inserted since the copy was taken: it is not pasted, and that is said.
    await mount(page, await book());
    await addPlain(page);
    await view(page, '(view.copyChart(0), view.insertRows(0, 1))');
    await view(page, 'view.select(api.parseRange("D30"))');
    expect(await view(page, '(() => { try { view.pasteChart(); return "pasted"; } catch (error) { return view.localizeError(error); } })()')).toBe(
      'The chart cannot be pasted: rows, columns or sheets changed since it was copied. Copy it again.',
    );
    expect((await charts(page)).length).toBe(1);
  });
});
